mapper.select:
SELECT COUNT(1)
FROM ts_user_favorite
WHERE user_id = #{userId}
  AND resource_type = #{resourceType}
  AND resource_id = #{resourceId}
  AND status = 1

mapper.update:
UPDATE ts_user_favorite
SET status = 0,
    updated_at = #{now}
WHERE user_id = #{userId}
  AND resource_type = #{resourceType}
  AND resource_id = #{resourceId}
  AND status = 1
